class Solution {
public:
    long long maximumTripletValue(vector<int>& nums) {
        int n = nums.size();
        long long maxPrefix = max((long long)nums[0], (long long)nums[1]);
        long long maxDiff = (long long)nums[0] - nums[1];
        long long answer = 0;
        for (int k = 2; k < n; k++) {
            answer = max(answer, maxDiff * (long long)nums[k]);
            maxDiff = max(maxDiff, maxPrefix - (long long)nums[k]);
            maxPrefix = max(maxPrefix, (long long)nums[k]);
        }
        return answer;
    }
};
